private static String freshDeviceToken(URI root, KeyPair device, String connectionId) throws Exception {
    HttpClient client = HttpClient.newHttpClient();
    JsonNode challenge = json(client, post(root.resolve("/api/v1/auth/challenge"), Map.of(
            "tenantId", "tenant-1", "deviceId", "device-1", "connectionId", connectionId,
            "authAlgorithm", HostDeviceStore.DEVICE_AUTH_ALGORITHM)).build(), 201);
    Signature signer = Signature.getInstance("SHA256withECDSA");
    signer.initSign(device.getPrivate());
    signer.update(io.github.diodeme.ji.relay.DeviceChallengeService.payload(
            "tenant-1", "device-1", connectionId, challenge.path("nonce").asText()));
    JsonNode verified = json(client, post(root.resolve("/api/v1/auth/verify"), Map.of(
            "tenantId", "tenant-1", "deviceId", "device-1", "connectionId", connectionId,
            "authAlgorithm", HostDeviceStore.DEVICE_AUTH_ALGORITHM,
            "signature", Base64.getEncoder().encodeToString(signer.sign()))).build(), 200);
    return verified.path("accessToken").asText();
}

